import test from 'node:test';import assert from 'node:assert/strict';import {validateSave} from '../save-validation.js?v=5.6.0';import {World} from '../world.js';import {source} from './opening-flow.mjs';
test('save preflight validates a fresh isolated world without altering the active journey',()=>{const w=new World(source),before=w.save(),value={schema:'ash-aether.enhanced-save/1',world:JSON.parse(before)};const input=JSON.stringify(value),checked=validateSave(source,value);assert.notEqual(checked,value);assert.equal(checked.world.mode,'field');assert.equal(JSON.stringify(value),input);assert.equal(w.save(),before);const bad=JSON.parse(JSON.stringify(value));bad.world.scene=-1;assert.throws(()=>validateSave(source,bad),/Invalid enhanced save/);assert.equal(w.save(),before);});
test('truncated battle snapshots fail before the active world is touched',()=>{const w=new World(source),value={schema:'ash-aether.enhanced-save/1',world:JSON.parse(w.save()),battle:{heroes:[]}};assert.throws(()=>validateSave(source,value),/incomplete/);assert.throws(()=>validateSave(source,{schema:'other'}),/Choose/);});

import {Battle,makeEnemy} from '../battle.js?v=5.6.0';import {defaultHero,compileTechnique} from '../mako.js';
function encounterSave(support='echo'){
 const w=new World(source);w.newGame({quiet:true});w.state.heroes[0]={...defaultHero(0),x:w.state.x,y:w.state.y};
 const e={...makeEnemy('boss',1,0,true),x:w.state.x+3,y:w.state.y};const b=new Battle({heroes:w.activeHeroes,enemies:[e],chapter:1});b.heroes[0].atb=1;b.command(0,'tech',e.id,compileTechnique('flame',support));
 return {schema:'ash-aether.enhanced-save/1',world:JSON.parse(w.save()),origin:{scene:w.scene.location,type:'practice',practice:{type:'practice',xy:[e.x,e.y],enemies:[['practice',[e.x,e.y]]]}},battle:b.snapshot()};
}
test('battle imports rehearse echo and persistent field resumption on isolated actors',()=>{for(const support of ['echo','field']){const value=encounterSave(support),before=JSON.stringify(value),checked=validateSave(source,value);assert.equal(JSON.stringify(value),before);const w=new World(source);w.restore(checked.world);const b=new Battle({heroes:w.activeHeroes,enemies:[],chapter:1});b.restore(checked.battle);const hp=b.enemies[0].hp;for(let n=0;n<25;n++)b.advance(.1);assert.ok(b.enemies[0].hp<hp,support);}});
test('corrupt actors, stale scenes and incomplete delayed effects fail before changing an active journey',()=>{const active=new World(source),before=active.save();for(const mutate of [v=>v.battle.heroes[0].status=null,v=>delete v.battle.delayed[0].tech,v=>v.battle.delayed[0].targets=null,v=>v.battle.enemies[0].hp=-1,v=>v.battle.heroes.push(v.battle.heroes[0]),v=>v.origin.scene=-1]){const v=encounterSave();mutate(v);assert.throws(()=>validateSave(source,v));assert.equal(active.save(),before);}});
test('identity and supply corruption cannot enter a journey through an imported world',()=>{const base={schema:'ash-aether.enhanced-save/1',world:JSON.parse(new World(source).save())};for(const mutate of [v=>v.world.heroes[1].id=0,v=>v.world.heroes[0].loadout=null,v=>v.world.items.tonic=-2,v=>v.world.recruited=[],v=>v.world.story.journal=null]){const v=structuredClone(base);mutate(v);assert.throws(()=>validateSave(source,v));}});

import {startOrigin,exitOrigin} from '../field-origins.js?v=5.6.0';
test('field-trial save preflight protects the full main-journey return state',()=>{const w=new World(source);w.newGame({originId:'sable-reed'});w.state.mode='field';const original=JSON.parse(w.save());startOrigin(w,4,'courier');const value={schema:'ash-aether.enhanced-save/1',world:JSON.parse(w.save())},checked=validateSave(source,value),restored=new World(source);restored.restore(checked.world);exitOrigin(restored,false);for(const key of ['scene','items','party','chronicle','gold','xp'])assert.deepEqual(restored.state[key],original[key]);for(const mutate of [v=>v.world.fieldOrigins.active.base.scene=-1,v=>v.world.fieldOrigins.active.base.heroes[0].id=5,v=>v.world.fieldOrigins.active.base.fieldOrigins.active={},v=>delete v.world.fieldOrigins.active]){const v=structuredClone(value);mutate(v);assert.throws(()=>validateSave(source,v));}});
